country_query:
SELECT DISTINCT ?company ?companyLabel WHERE {
 VALUES ?type { wd:Q4830453 wd:Q783794 wd:Q891723 wd:Q6881511 wd:Q167037 wd:Q726870 wd:Q18127 wd:Q2085381 wd:Q134161 wd:Q730038 wd:Q778575 }
 ?company wdt:P17 wd:Q334; wdt:P31 ?type.
 FILTER NOT EXISTS { ?company wdt:P576 ?dissolved }
 SERVICE wikibase:label { bd:serviceParam wikibase:language "en,mul" }
}

headquarters_query:
SELECT DISTINCT ?company ?companyLabel WHERE {
 VALUES ?type { wd:Q4830453 wd:Q783794 wd:Q891723 wd:Q6881511 wd:Q167037 wd:Q726870 wd:Q18127 wd:Q2085381 wd:Q134161 wd:Q730038 wd:Q778575 }
 { ?company wdt:P159 wd:Q334 } UNION { ?company wdt:P159/wdt:P17 wd:Q334 }
 ?company wdt:P31 ?type.
 FILTER NOT EXISTS { ?company wdt:P576 ?dissolved }
 SERVICE wikibase:label { bd:serviceParam wikibase:language "en,mul" }
}
